"""Generated by generators/linear_recurrence.py (companion-matrix power). Do not edit by hand; regenerate instead."""

COEFFS = (1, 0, 1)
INIT = (0, 0, 1)
MASK = (1 << 64) - 1


def _mul(A, B):
    k = len(A)
    return [[sum(A[i][t] * B[t][j] for t in range(k)) & MASK for j in range(k)] for i in range(k)]


def solve(n: int) -> int:
    """(a(m), ..., a(m-k+1)) = C^(m-k+1) (a(k-1), ..., a(0)) for the companion matrix C; Theta(k^3 log n)."""
    k = len(INIT)
    if n < k:
        return INIT[n]
    C = [list(COEFFS)] + [[1 if j == i else 0 for j in range(k)] for i in range(k - 1)]
    R = [[1 if i == j else 0 for j in range(k)] for i in range(k)]
    for bit in bin(n - k + 1)[2:]:  # left-to-right square-and-multiply
        R = _mul(R, R)
        if bit == "1":
            R = _mul(R, C)
    state = list(reversed(INIT))
    return sum(R[0][j] * state[j] for j in range(k)) & MASK
